#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#define  MAX_VARS 2048
const char *program = "echo Hello, World!";
int pc = 0; char var_names[MAX_VARS][32]; int var_values[MAX_VARS]; int var_count = 0; int find_var(const char *name) { for (int i = 0; i < var_count; i++) { if (strcmp(var_names[i], name) == 0) { return i; } } return -1; } void set_var(const char *name, int value) { int idx = find_var(name); if (idx != -1) { var_values[idx] = value; return; } strcpy(var_names[var_count], name); var_values[var_count] = value; var_count++; } int resolve_value(const char *token) { if (isdigit(token[0]) || (token[0] == '-' && isdigit(token[1]))) { return atoi(token); } int idx = find_var(token); return (idx != -1) ? var_values[idx] : 0; } int main() { printf("Alisa Atom 1.0\n"); printf("Parsing script...\n"); char code[16384]; strcpy(code, program); int skipblock = 0, loop_start = -1, line_count = 0; char *lines[1024]; char *tok = strtok(code, "\n"); while (tok != NULL) { lines[line_count++] = tok; tok = strtok(NULL, "\n"); } while (pc < line_count) { char *line = lines[pc]; if (strcmp(line, "end") == 0) { if (skipblock) { skipblock = 0; } else if (loop_start != -1) { pc = loop_start; continue; } } else if (!skipblock) { if (strncmp(line, "let ", 4) == 0) { char name[32], left[32], right[32]; char op; if (sscanf(line + 4, "%31s = %31s %c %31s", name, left, &op, right) == 4) { int val1 = resolve_value(left); int val2 = resolve_value(right); int result = 0; if (op == '+') result = val1 + val2; else if (op == '-') result = val1 - val2; else if (op == '*') result = val1 * val2; else if (op == '/') { if (val2 != 0) result = val1 / val2; else printf("Error: Division by zero\n"); } set_var(name, result); } else if (sscanf(line + 4, "%31s = %31s", name, left) == 2) { set_var(name, resolve_value(left)); } } else if (strncmp(line, "while ", 6) == 0) { char left_str[32], right_str[32]; if (sscanf(line + 6, "%31[^=]=%31s", left_str, right_str) == 2) { if (resolve_value(left_str) == resolve_value(right_str)) { loop_start = pc; } else { loop_start = -1; skipblock = 1; } } } else if (strncmp(line, "if ", 3) == 0) { char left_str[32], right_str[32]; if (sscanf(line + 3, "%31[^=]=%31s", left_str, right_str) == 2) { if (resolve_value(left_str) != resolve_value(right_str)) { skipblock = 1; } } } else if (strncmp(line, "echo ", 5) == 0) { char *arg = line + 5; int idx = find_var(arg); if (idx != -1) { printf("%d\n", var_values[idx]); } else { printf("%s\n", arg); } }} pc++; } return 0; }
